void thermal_model_reset(void)
{
    for (int i = 0; i < THERMAL_MODEL_WINDOW_SIZE; ++i) {
        s_window[i] = 0.0f;
    }
    s_write_index = 0;
    s_sample_count = 0;
}

bool thermal_model_is_ready(void)
{
    return s_sample_count >= THERMAL_MODEL_WINDOW_SIZE;
}

int thermal_model_samples_collected(void)
{
    return s_sample_count;
}

static void build_ordered_window(float ordered[THERMAL_MODEL_WINDOW_SIZE])
{
    if (s_sample_count < THERMAL_MODEL_WINDOW_SIZE) {
        int pad_count = THERMAL_MODEL_WINDOW_SIZE - s_sample_count;
        for (int i = 0; i < pad_count; ++i) {
            ordered[i] = 0.0f;
        }
        for (int i = 0; i < s_sample_count; ++i) {
            ordered[pad_count + i] = s_window[i];
        }
        return;
    }

    for (int i = 0; i < THERMAL_MODEL_WINDOW_SIZE; ++i) {
        int source_index = (s_write_index + i) % THERMAL_MODEL_WINDOW_SIZE;
        ordered[i] = s_window[source_index];
    }
}

float thermal_model_predict_window(const float p_loss_window_w[THERMAL_MODEL_WINDOW_SIZE])
{
    float x[INPUT_SIZE];
    float h1[HIDDEN1_SIZE];
    float h2[HIDDEN2_SIZE];

    for (int i = 0; i < INPUT_SIZE; ++i) {
        float clipped = clampf_local(p_loss_window_w[i], THERMAL_MODEL_PLOSS_MIN_W, THERMAL_MODEL_PLOSS_MAX_W);
        x[i] = (clipped - THERMAL_MODEL_PLOSS_MIN_W) /
               (THERMAL_MODEL_PLOSS_MAX_W - THERMAL_MODEL_PLOSS_MIN_W);
    }

    for (int row = 0; row < HIDDEN1_SIZE; ++row) {
        float sum = B0[row];
        for (int col = 0; col < INPUT_SIZE; ++col) {
            sum += W0[(row * INPUT_SIZE) + col] * x[col];
        }
        h1[row] = relu(sum);
    }

    for (int row = 0; row < HIDDEN2_SIZE; ++row) {
        float sum = B1[row];
        for (int col = 0; col < HIDDEN1_SIZE; ++col) {
            sum += W1[(row * HIDDEN1_SIZE) + col] * h1[col];
        }
        h2[row] = relu(sum);
    }

    float scaled_delta_t = B2[0];
    for (int col = 0; col < HIDDEN2_SIZE; ++col) {
        scaled_delta_t += W2[col] * h2[col];
    }

    return (scaled_delta_t * (THERMAL_MODEL_DELTA_T_MAX_C - THERMAL_MODEL_DELTA_T_MIN_C)) +
           THERMAL_MODEL_DELTA_T_MIN_C;
}

bool thermal_model_update(float p_loss_w, float *predicted_delta_t_c)
{
    s_window[s_write_index] = p_loss_w;
    s_write_index = (s_write_index + 1) % THERMAL_MODEL_WINDOW_SIZE;
    if (s_sample_count < THERMAL_MODEL_WINDOW_SIZE) {
        s_sample_count++;
    }

    float ordered_window[THERMAL_MODEL_WINDOW_SIZE];
    build_ordered_window(ordered_window);

    if (predicted_delta_t_c != NULL) {
        *predicted_delta_t_c = thermal_model_predict_window(ordered_window);
    }

    return thermal_model_is_ready();
}
